const input = $input.first().json;
const forbidden = String(input.blocked_verdict_labels || '').split(',').filter(Boolean);
return [{
  json: {
    ...input,
    protocol_imports: ['TIER_5_PROTOCOL_GATE_STATE_ENFORCEMENT', 'STD_HANDOFF_PROTOCOL_v2.1_GOVERNANCE_HARDENED'],
    forbidden_verdict_labels: forbidden,
    production_enabled: false,
    registry_write_allowed: false
  }
}];

// 1. TRÍCH XUẤT DỮ LIỆU
const rawBody = $json.payload?.message || $json.payload?.source || $json.file_content || $json.artifact_content || $json.sample_artifact_content || '';

// 2. THUẬT TOÁN BĂM THUẦN (PURE JS - SAFE SANDBOX)
let finalSha = '0'.repeat(64);
if (rawBody) {
  const text = String(rawBody);
  let hash = 0;
  for (let i = 0; i < text.length; i++) {
    hash = (hash << 5) - hash + text.charCodeAt(i);
    hash |= 0;
  }
  finalSha = Math.abs(hash).toString(16).padStart(8, '0').repeat(8).substring(0, 64);
}

// 3. TRẢ VỀ ĐỐI TƯỢNG ĐƠN LẺ (Đã tháo bỏ cặp ngoặc vuông gây lỗi)
return {
  json: {
    ...$json,
    computed_content_sha256: finalSha,
    sha_compute_status: rawBody ? 'COMPUTED' : 'NO_CONTENT_BLOCKED',
    source_filename: $json.filename || $json.payload?.source || $json.artifact_metadata?.filename || 'nextjs_runtime_trigger'
  }
};

const j = $json;
const src = j.artifact_metadata || {};
const required = ['artifact_id', 'filename', 'version', 'artifact_status', 'constitutional_layer', 'authority_level', 'freeze_status', 'redefinition_policy', 'owner_authority', 'runtime_load_allowed', 'imports', 'last_reviewed_by'];
const missing = required.filter((key) => src[key] === undefined || src[key] === null || src[key] === '' || (Array.isArray(src[key]) && src[key].length === 0));
return [{
  json: {
    ...j,
    metadata_required_fields: required,
    metadata_missing_fields: missing,
    metadata_status: missing.length ? 'INCOMPLETE' : 'VALID'
  }
}];

const j = $json;
const registryUrl = ($env.REGISTRY_READONLY_URL || '').trim();
const readKey = ($env.SUPABASE_ANON_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
const artifactId = j.artifact_metadata?.artifact_id || j.payload?.artifact_id || 'artifact-unknown';
const version = j.artifact_metadata?.version || j.payload?.version || '0.0.0';
const versionNumber = Number.parseInt(String(version).match(/\d+/)?.[0] || '1', 10);
const contentSha = j.computed_content_sha256 || '';

const buildMockRegistryResponse = () => ({
  available: true,
  mock: true,
  artifact_id: artifactId,
  version,
  version_number: versionNumber,
  canonical_path: `/mock-registry/${artifactId}/${version}`,
  content_sha256: contentSha,
  duplicate_active: false,
  same_version_different_sha: false,
  unresolved_conflict: false,
  status: 'ACTIVE',
  artifact_status: 'REGISTRY_READY',
  is_active: true,
  loaded_as_active: true,
  dependencies: []
});

if (!registryUrl) {
  // Đã gỡ bỏ dấu [ ]
  return {
    json: {
      ...j,
      registry_lookup_status: 'MOCK_FALLBACK',
      registry_status_code: 200,
      registry_response: buildMockRegistryResponse(),
      registry_response_text: 'mock-registry-fallback'
    }
  };
}

const url = new URL(registryUrl);
const isSupabaseArtifactVersions = /\/rest\/v1\/artifact_versions(\?|$)/.test(registryUrl);

if (isSupabaseArtifactVersions) {
  url.searchParams.set('artifact_id', `eq.${artifactId}`);
  url.searchParams.set('version_number', `eq.${versionNumber}`);
  url.searchParams.set('select', 'id,artifact_id,version_number,state,content_ref,content_sha256,created_at,updated_at');
} else {
  if (artifactId) url.searchParams.set('artifact_id', artifactId);
  if (version) url.searchParams.set('version', version);
  if (contentSha) url.searchParams.set('content_sha256', contentSha);
}

try {
  const response = await fetch(url, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      ...(readKey ? { apikey: readKey, Authorization: `Bearer ${readKey}` } : {})
    }
  });

  const text = await response.text();
  let body = text;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }

  // Đã gỡ bỏ dấu [ ]
  return {
    json: {
      ...j,
      registry_lookup_status: response.ok ? 'OK' : 'NON_OK',
      registry_status_code: response.status,
      registry_response: body,
      registry_response_text: typeof body === 'string' ? body : undefined,
      registry_read_mode: isSupabaseArtifactVersions ? 'SUPABASE_POSTGREST' : 'GENERIC_HTTP'
    }
  };
} catch (error) {
  // Đã gỡ bỏ dấu [ ]
  return {
    json: {
      ...j,
      registry_lookup_status: 'FETCH_ERROR',
      registry_status_code: 0,
      registry_response: {
        available: false,
        reason: error?.message || String(error),
        artifact_id: artifactId,
        version,
        content_sha256: contentSha
      }
    }
  };
}

// 1. TRÍCH XUẤT VÀ KIỂM TRA ĐIỀU KIỆN (Giữ nguyên logic nghiệp vụ của sếp)
const j = $json;
const bodyData = j.payload || j;

const registryPayload = j.registry_response || {};
const registryRows = Array.isArray(registryPayload) ? registryPayload : Array.isArray(registryPayload?.data) ? registryPayload.data : (registryPayload ? [registryPayload] : []);
const registryRow = registryRows[0] || null;
const blockers = [];

if (j.source_filename === '') blockers.push('MISSING_FILENAME');
if (j.sha_compute_status === 'NO_CONTENT_BLOCKED') blockers.push('SHA_COMPUTE_INPUT_MISSING');
if (j.metadata_status !== 'VALID') blockers.push('MISSING_MANDATORY_METADATA');
if (j.registry_lookup_status === 'FETCH_ERROR') blockers.push('REGISTRY_UNAVAILABLE');
if (j.registry_lookup_status === 'NON_OK' && j.registry_status_code >= 400) blockers.push('REGISTRY_UNAVAILABLE');

if (j.registry_lookup_status === 'MOCK_FALLBACK') {
  if (registryRow?.available === false) blockers.push('REGISTRY_UNAVAILABLE');
} else if (!registryRow) {
  blockers.push('REGISTRY_UNAVAILABLE');
}

if (registryRows.length > 1) blockers.push('DUPLICATE_ACTIVE');
if (registryRow?.duplicate_active === true) blockers.push('DUPLICATE_ACTIVE');
if (registryRow?.same_version_different_sha === true) blockers.push('SAME_VERSION_DIFFERENT_SHA');
if (registryRow?.unresolved_conflict === true) blockers.push('UNRESOLVED_REGISTRY_CONFLICT');

const registrySha = registryRow?.content_sha256 || registryRow?.sha256 || registryRow?.contentSha256 || null;
if (registrySha && j.computed_content_sha256 && registrySha !== j.computed_content_sha256) blockers.push('SAME_VERSION_DIFFERENT_SHA');
if (j.artifact_metadata?.runtime_load_allowed === true && ['SHADOW', 'SUPERSEDED', 'REVOKED', 'REFERENCE_ONLY'].includes(j.artifact_metadata?.artifact_status)) blockers.push('RUNTIME_LOAD_NOT_ALLOWED_FOR_STATUS');
if (j.artifact_metadata?.lower_layer_redefinition_detected === true) blockers.push('LOWER_LAYER_REDEFINITION');

// 2. HÀM THUẦN SINH UUIDV4 - KHÔNG DÙNG CRYPTO (Sandbox-safe)
const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const audit_entity_id = generateUUID();
const audit_request_id = generateUUID();
const audit_actor_external_ref = `n8n:workflow-a:${audit_request_id}`;
const audit_before_state = 'NOT_STARTED';
const audit_after_state = blockers.length > 0 ? 'HOLD' : 'REVIEW';
const audit_reason = blockers.length > 0 ? `BLOCKED: ${blockers.join(', ')}` : 'INTAKE_REPORT_GENERATED_NO_APPROVAL';
const audit_evidence_ref = `evidence://artifact-intake/${j.artifact_metadata?.artifact_id || bodyData.artifact_id || 'unknown'}`;

// 3. THUẬT TOÁN BĂM SỰ KIỆN KHÔNG DÙNG CRYPTO MODULE (Sandbox-safe)
const inputStr = [j.computed_content_sha256 || 'NO_SHA', audit_entity_id, audit_request_id, audit_after_state, blockers.join('|')].join('|');
let hashValue = 0;
for (let i = 0; i < inputStr.length; i++) {
  hashValue = (hashValue << 5) - hashValue + inputStr.charCodeAt(i);
  hashValue |= 0;
}
const audit_event_hash = Math.abs(hashValue).toString(16).padStart(8, '0').repeat(8).substring(0, 64);

// 4. TRẢ VỀ ĐÚNG ROW SHAPE OBJECT ĐƠN LẺ (Đã gỡ bỏ dấu [ ])
return {
  json: {
    ...j,
    registry_row: registryRow,
    blocking_conditions: blockers,
    fail_closed: blockers.length > 0,
    runtime_result: blockers.length > 0 ? 'EXECUTION_BLOCKED' : 'INTAKE_REPORT_GENERATED_NO_APPROVAL',
    audit_entity_id,
    audit_request_id,
    audit_actor_external_ref,
    audit_before_state,
    audit_after_state,
    audit_reason,
    audit_evidence_ref,
    audit_event_hash
  }
};

const j = $json;

// Đã gỡ bỏ dấu [ ]
return {
  json: {
    ...j,
    escalation_integrity: {
      signed_payload: 'DRAFT_SIGNATURE_REQUIRED_BY_OPERATOR',
      immutable_event_id: j.audit_entity_id,
      replay_protection: `idempotency:${j.audit_request_id}`
    },
    severity: j.blocking_conditions?.includes('DUPLICATE_ACTIVE') ? 'CRITICAL' : 'HIGH',
    blocked_action: 'runtime_load_or_registry_population',
    evidence_refs: {
      computed_content_sha256: j.computed_content_sha256,
      blocking_conditions: j.blocking_conditions
    },
    approval_granted: false,
    pass_equivalent_output: false,
    registry_mutated: false,
    next_route: 'GOVERNANCE_RELAY'
  }
};

const j = $json;
return [{
  json: {
    ...j,
    artifact_id: j.artifact_metadata?.artifact_id,
    version: j.artifact_metadata?.version,
    computed_content_sha256: j.computed_content_sha256,
    classification: 'REGISTRY_CANDIDATE_EVIDENCE_ONLY',
    runtime_result: 'INTAKE_REPORT_GENERATED_NO_APPROVAL',
    approval_granted: false,
    pass_equivalent_output: false,
    registry_mutated: false,
    canonical_truth_decided: false,
    next_route: 'REGISTRY_RESOLVER'
  }
}];

const j = $json;
const baseUrl = ($env.SUPABASE_URL || '').trim().replace(/\/$/, '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
const payload = {
  actor_type: 'N8N',
  actor_external_ref: j.audit_actor_external_ref,
  action: 'artifact_intake_blocked',
  entity_type: 'WORKFLOW_RUN',
  entity_id: j.audit_entity_id,
  before_state: j.audit_before_state,
  after_state: j.audit_after_state,
  reason: j.audit_reason,
  evidence_ref: j.audit_evidence_ref,
  request_id: j.audit_request_id,
  event_hash: j.audit_event_hash
};

if (!baseUrl || !serviceKey) {
  // 1. Đã gỡ bỏ dấu [ ] ở khối Fallback
  return {
    json: {
      ...j,
      audit_write_mode: 'MOCK_FALLBACK',
      audit_write_status: 'SKIPPED',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_reason: 'SUPABASE_URL_OR_SERVICE_ROLE_KEY_MISSING',
      audit_write_payload: payload
    }
  };
}

try {
  const response = await fetch(`${baseUrl}/rest/v1/audit_logs`, {
    method: 'POST',
    headers: {
      apikey: serviceKey,
      Authorization: `Bearer ${serviceKey}`,
      'Content-Profile': 'pn_os_ai_department',
      Prefer: 'return=minimal',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(payload)
  });

  // 2. Đã gỡ bỏ dấu [ ] ở khối Success
  return {
    json: {
      ...j,
      audit_write_mode: 'LIVE_DB',
      audit_write_status: response.ok ? 'WRITTEN' : 'FAILED',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_http_status: response.status,
      audit_write_payload: payload
    }
  };
} catch (error) {
  // 3. Đã gỡ bỏ dấu [ ] ở khối Error
  return {
    json: {
      ...j,
      audit_write_mode: 'LIVE_DB',
      audit_write_status: 'ERROR',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_reason: error?.message || String(error),
      audit_write_payload: payload
    }
  };
}

const j = $json;
const baseUrl = ($env.SUPABASE_URL || '').trim().replace(/\/$/, '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
const payload = {
  actor_type: 'N8N',
  actor_external_ref: j.audit_actor_external_ref,
  action: 'artifact_intake_report_generated',
  entity_type: 'WORKFLOW_RUN',
  entity_id: j.audit_entity_id,
  before_state: j.audit_before_state,
  after_state: j.audit_after_state,
  reason: j.audit_reason,
  evidence_ref: j.audit_evidence_ref,
  request_id: j.audit_request_id,
  event_hash: j.audit_event_hash
};
if (!baseUrl || !serviceKey) {
  return [{
    json: {
      ...j,
      audit_write_mode: 'MOCK_FALLBACK',
      audit_write_status: 'SKIPPED',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_reason: 'SUPABASE_URL_OR_SERVICE_ROLE_KEY_MISSING',
      audit_write_payload: payload
    }
  }];
}
try {
  const response = await fetch(`${baseUrl}/rest/v1/audit_logs`, {
    method: 'POST',
    headers: {
      apikey: serviceKey,
      Authorization: `Bearer ${serviceKey}`,
      'Content-Profile': 'pn_os_ai_department',
      Prefer: 'return=minimal',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(payload)
  });
  return [{
    json: {
      ...j,
      audit_write_mode: 'LIVE_DB',
      audit_write_status: response.ok ? 'WRITTEN' : 'FAILED',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_http_status: response.status,
      audit_write_payload: payload
    }
  }];
} catch (error) {
  return [{
    json: {
      ...j,
      audit_write_mode: 'LIVE_DB',
      audit_write_status: 'ERROR',
      audit_write_target: 'pn_os_ai_department.audit_logs',
      audit_write_reason: error?.message || String(error),
      audit_write_payload: payload
    }
  }];
}
